-- WhyTheyNameThisWay dictionary.
-- Each entry: E("lowercase name or word", "meaning", "roots", "example sentence")
-- Whole names (e.g. "westfall") are checked first; otherwise each word is looked up.
-- Add your own entries at the bottom!
local ADDON, ns = ...
local D = {}
ns.D = D
local function E(key, meaning, roots, example)
    if not meaning or meaning == "" then return end -- placeholder, nothing to teach yet
    if D[key] then return end                       -- first (richer) definition wins
    D[key] = { meaning, roots, example }
end

